        LPITEMIDLIST pidl = SHBrowseForFolderW(&bi);
        if (pidl) { if (SHGetPathFromIDListW(pidl, buf)) SetDlgItemText(IDC_LG_FOLDER, buf); CoTaskMemFree(pidl); }
