                    int bufLen = (int)dw->SendDlgItemMessage(dw->CtrlIdOf(ctrlId), getLenMsg, i, 0);
                    if (bufLen < 0) { items.push_back(CString()); continue; }
                    std::vector<wchar_t> buf(bufLen + 1);
